import math

def build_agent(sandbox):
    # Base beam anchored to glass at safe height
    base = sandbox.add_beam(x=6.0, y=2.15, width=0.5, height=0.12, angle=0, density=1.0)
    if hasattr(sandbox, 'weld_to_glass'):
        sandbox.weld_to_glass(base, (6.0, 2.0))

    # Create a wiper beam covering full 12m length at optimal height
    seg_centers = [i * 2.0 for i in range(0, 7)]  # 0.0 to 12.0 in 2.0m steps
    bars = []
    for cx in seg_centers:
        b = sandbox.add_beam(x=cx, y=2.2, width=2.0, height=0.24, angle=0, density=1.0)
        sandbox.set_material_properties(b, restitution=0.0, friction=3.0)
        bars.append(b)

    # Connect bars rigidly to form a single long beam
    for i in range(len(bars) - 1):
        jx = (seg_centers[i] + seg_centers[i+1]) / 2.0
        sandbox.add_joint(bars[i], bars[i+1], (jx, 2.2), type='rigid')

    # Full rotation pivot joint for sweeping motion
    pivot = sandbox.add_joint(
        base, bars[2], (6.0, 2.2), type='pivot',
        lower_limit=-math.pi, upper_limit=math.pi
    )
    return {"body": base, "motors": [pivot]}

def agent_action(sandbox, agent_body, step_count):
    motors = agent_body.get("motors", []) if isinstance(agent_body, dict) else []
    if not motors:
        return

    if hasattr(sandbox, 'set_awake'):
        for body in sandbox.bodies:
            sandbox.set_awake(body, True)

    # Increased motor speed for effective particle removal
    motor_speed = 15.0  # rad/s
    sandbox.set_motor(motors[0], motor_speed, max_torque=1.0)
